const lv_image_dsc_t *board7_icon_descriptor(const char *name, int requested_size) {
    if(name == nullptr) return nullptr;
    int wanted = requested_size <= 24 ? 24 : (requested_size <= 32 ? 32 : 48);
    for(const IconRecord &icon : kIcons) {
        if(icon.size == wanted && std::strcmp(icon.name, name) == 0) return icon.dsc;
    }
    for(const IconRecord &icon : kIcons) {
        if(std::strcmp(icon.name, name) == 0) return icon.dsc;
    }
    return nullptr;
}

std::size_t board7_icon_memory_bytes() {
    std::size_t total = 0;
    for(const IconRecord &icon : kIcons) total += icon.bytes;
    return total;
}

